// SigJSON+ - format round-trip demo
var data = { name: "sensor-1", readings: [21.5, 22.1, 20.9] };
var json = JSON.stringify(data);
var back = JSON.parse(json);
var ok = back.name === data.name && back.readings.length === 3;
console.log("Format: SigJSON+ | Encoding: UTF-8 text");
console.log("Serialized: " + json.length + " bytes");
console.log("Round-trip preserves data -> " + (ok ? "PASS" : "FAIL"));
console.log("Schema: optional inline | Best for: Sig configs");

